package counter

import "unicode"

// counter is a concrete implementation of the Counter interface.
//
// It accumulates strings via AddString and reports the total number of
// lines, letters (Unicode letters) and characters (runes) seen so far.
type counter struct {
	newlines   int
	lastChar   rune
	characters int
	letters    int
}

// New returns a ready-to-use Counter.
func New() Counter {
	return &counter{}
}

// AddString adds s to the running totals.
func (c *counter) AddString(s string) {
	for _, char := range s {
		c.lastChar = char
		if char == '\n' {
			c.newlines++
		} else if unicode.IsLetter(char) {
			c.letters++
		}
		c.characters++
	}
}

// Lines reports the number of lines. A trailing newline does not start a
// new (empty) line, so a string that ends with a newline has as many lines
// as it has newlines; otherwise it has one more line than newlines.
// An empty counter reports zero lines.
func (c counter) Lines() int {
	switch {
	case c.characters == 0:
		return 0
	case c.lastChar == '\n':
		return c.newlines
	default:
		return c.newlines + 1
	}
}

// Letters reports the number of Unicode letters.
func (c counter) Letters() int { return c.letters }

// Characters reports the total number of runes.
func (c counter) Characters() int { return c.characters }

package counter

import "testing"

// Temporary verification only; deleted after running.
func TestTmpVerify(t *testing.T) {
	cases := []struct {
		name       string
		strings    []string
		lines      int
		letters    int
		characters int
	}{
		{"empty", nil, 0, 0, 0},
		{"one word no newline", []string{"hello"}, 1, 5, 5},
		{"trailing newline", []string{"hello\n"}, 1, 5, 6},
		{"two lines no trailing nl", []string{"a\nb"}, 2, 2, 3},
		{"two lines trailing nl", []string{"a\nb\n"}, 2, 2, 4},
		{"multiple adds", []string{"ab", "c\nd"}, 2, 4, 6},
		{"unicode letters", []string{"héllo wörld"}, 1, 11, 11},
		{"unicode multi-byte rune count", []string{"é"}, 1, 1, 1}, // é is 1 rune, 2 bytes
		{"cjk", []string{"你好\n"}, 1, 2, 3},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			c := New()
			for _, s := range tc.strings {
				c.AddString(s)
			}
			if got := c.Lines(); got != tc.lines {
				t.Errorf("Lines() = %d, want %d", got, tc.lines)
			}
			if got := c.Letters(); got != tc.letters {
				t.Errorf("Letters() = %d, want %d", got, tc.letters)
			}
			if got := c.Characters(); got != tc.characters {
				t.Errorf("Characters() = %d, want %d", got, tc.characters)
			}
		})
	}
}
